// The wire types, from the one place that writes them.
//
// `platform/contract/generated/types/contract.ts` is generated by `contract-gen` and checked by CI
// (`platform/contract/README.md:18-23`). Nothing in this folder redeclares a wire type: a hand
// written copy is a second contract, and the second one is always the wrong one. This file only
// names the types the Roku screens use, so the import sites stay short.
//
// `tsconfig.json` carries the generated file in `include` for this reason.

/**
 * The values the generator emits. `ADDRESS` is the whole address table, all 22 entries
 * (`platform/contract/generated/types/contract.ts:6-29`, from `platform/contract/src/address.rs`).
 * Nothing in this folder writes an address as a string.
 */
export { ABI_VERSION, ADDRESS, WIRE_VERSION } from "../../../platform/contract/generated/types/contract";

export type {
  Action,
  Badge,
  Cursor,
  DeviceSignInView,
  EpisodeRef,
  Image,
  More,
  NavItem,
  Profile,
  Rating,
  Resume,
  RouteTarget,
  Screen,
  ScreenName,
  Season,
  SeasonSummary,
  Section,
  SectionKind,
  Target,
  Tile,
  TitleDetail,
  TitleKey,
  Track,
  View,
} from "../../../platform/contract/generated/types/contract";
